data.query:
query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!]) {
  inventory(where: $where, orderBy: $orderBy, first: 1) {
    edges {
      node {
        id
        quantity {
          value
          unitId
        }
        inventoryStatusId
        locationId
        productStrategyProcessId
        theoreticalWeight
        weightUnitId
      }
    }
  }
}

data.mutation:
mutation createUpdateInventory($createPayload:[InventoryCreatePayloadInput!]!,$updatePayload:[InventoryUpdatePayloadInput!]!){
  createInventory(payload:$createPayload){
    id
    number
    productStrategyProcessId
    inventoryStatusId
    locationId
  }
  updateInventory(payload:$updatePayload){
    id
    number
    productStrategyProcessId
    locationId
  }
}

data.variablesTransform:
(

$i := $state.context.LOCAL.inventory;
  {
    "payload": [
      $.createInventory.{
        "create": {
          "transactionTypeId": "Inventory Split",
          "customData": $state.claims,
          "sourceQuantity": {
            "value": $i.quantity.value,
            "unitId": $i.quantity.unitId
          },
          "sourceLocationId": locationId,
          "sourceInventoryId": $i.id,
          "sourceInventoryStatusId": inventoryStatusId,      
          "sourceProductStrategyProcessId": productStrategyProcessId,

          "destinationQuantity": {
            "value": $state.context.REQUEST.quantity,
            "unitId": $i.quantity.unitId
          },
          "destinationLocationId": locationId,
          "destinationInventoryId": id,
          "destinationInventoryStatusId": inventoryStatusId,
          "destinationProductStrategyProcessId": productStrategyProcessId
        }
      }
    ]
  }
)

